(async () => {
  const { readFileSync, existsSync } = await import('node:fs');
  const xmlPath = process.env.XML_PATH;
  if (!xmlPath) throw new Error('Missing XML_PATH');
  if (!existsSync(xmlPath)) throw new Error('XML file not found at ' + xmlPath);
  globalThis.xmlPath = xmlPath;
})();

(async () => {
  const { default: jsp } = await import('jsparsers');
  const xml = jsp.xml();
  await xml.readFile(globalThis.xmlPath);
  const tomlStr = xml.toml();
  globalThis.tomlResult = tomlStr;
})();
